diff --git a/tests/fixtures/fence-corpus/corpus.jsonl b/tests/fixtures/fence-corpus/corpus.jsonl
index 18d4a852..351e0814 100644
--- a/tests/fixtures/fence-corpus/corpus.jsonl
+++ b/tests/fixtures/fence-corpus/corpus.jsonl
@@ -181,3 +181,56 @@
 {"id":"D100","cmd":"git checkout --patch spike/ceiling-ui -- src/a.ts","expect":"block","rule":"SP-1","why":"the long form of the same patch copy, with a path","cwd":"repo"}
 {"id":"B77","cmd":"git checkout -p main","expect":"allow","rule":"SP-1","why":"a patch copy from the default branch names no spike","cwd":"repo"}
 {"id":"B78","cmd":"git format-patch -1 main","expect":"allow","rule":"SP-1","why":"format-patch of a non-spike ref; the spike form is a documented two-step miss","cwd":"repo"}
+{"id":"B79","cmd":"cat >> grimoires/loa/NOTES.md <<EOF\n- **Sprint 253**: SP-1 refused `git merge spike/ceiling-ui` typed inside this NOTES append (prose, not a command)\nEOF","expect":"allow","rule":"FR-6","why":"SP-1 prose case 1: a spike merge named mid-sentence in a NOTES append with an unquoted delimiter (the #1245 scrub did not cover it); the segment's command word is `-`, so the line is dropped","cwd":"repo"}
+{"id":"B80","cmd":"mkdir -p grimoires/loa/a2a/sprint-253 && cat > grimoires/loa/a2a/sprint-253/engineer-feedback.md <<'EOF'\n## LOW-3\nThe recipe git fetch origin spike/x && git merge FETCH_HEAD belongs to the ICE merge path, not to a heredoc.\nEOF","expect":"allow","rule":"FR-6","why":"SP-1 prose case 2: a compound header (mkdir && cat) writing a feedback file whose prose names the fetch+FETCH_HEAD one-liner; only the heredoc's own pipeline is classified","cwd":"repo"}
+{"id":"B81","cmd":"tee -a grimoires/loa/NOTES.md <<'EOF'\n- the fence (SP-1) blocked `git rebase spike/ceiling-ui` inside a review heredoc; recorded as a false positive\nEOF","expect":"allow","rule":"FR-6","why":"SP-1 prose case 3: tee -a to a plain .md with a spike rebase named mid-sentence","cwd":"repo"}
+{"id":"B82","cmd":"git commit -q -F - <<'EOF'\nfix(fence): SP-1 no longer blocks prose naming git merge spike/x inside a heredoc\nEOF","expect":"allow","rule":"FR-6","why":"SP-1 prose case 4: a commit message read from stdin naming a spike merge","cwd":"repo"}
+{"id":"B83","cmd":"gh pr comment 1279 -F - <<'EOF'\nThe reviewer's example `git cherry-pick spike/ceiling-ui~2` is refused by SP-1 by design.\nEOF","expect":"allow","rule":"FR-6","why":"SP-1 prose case 5: a PR comment body read from stdin naming a spike cherry-pick","cwd":"repo"}
+{"id":"B84","cmd":"cat > grimoires/loa/a2a/sprint-256/review.md <<EOF\n- the transcript's `git push --force origin main` was refused by P2, as intended\nEOF","expect":"allow","rule":"FR-6","why":"the P2 force-push string inside a heredoc redirected to a .md file, unquoted delimiter; the line's command word is `-`","cwd":"repo"}
+{"id":"B85","cmd":"br create --title \"fence false positive\" --description - <<'EOF'\nThe agent typed rm -rf ./build inside a NOTES heredoc and the fence blocked the append.\nEOF","expect":"allow","rule":"FR-6","why":"br create reading its description from stdin; the body quotes a recursive delete mid-sentence","cwd":"repo"}
+{"id":"B86","cmd":"gh pr comment 1281 -F - <<'EOF'\nThe `git push --force` to the record branch was blocked; use the temporary-index recipe.\nEOF","expect":"allow","rule":"FR-6","why":"gh pr comment -F - body naming a force push; `;` splits the line and neither segment starts with a fence verb","cwd":"repo"}
+{"id":"B87","cmd":"jq -f - evals/results/arms/review-recall/batch-1/STATUS.json <<'EOF'\n.per_arm | to_entries[] | select(.value.note != \"rm -rf src\")\nEOF","expect":"allow","rule":"FR-6","why":"a jq filter read from stdin (no in-place flag); the filter's pipes split into segments whose words are jq, not shell","cwd":"repo"}
+{"id":"B88","cmd":"git commit -q -F - <<'EOF'\nfix(fence): the FR-6 classifier stops blocking prose that mentions rm -rf src in a NOTES heredoc\nEOF","expect":"allow","rule":"FR-6","why":"a commit message read from stdin naming a destructive command mid-sentence","cwd":"repo"}
+{"id":"D101","cmd":"bash <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"shell consumer: the body is scanned in full","cwd":"repo"}
+{"id":"D102","cmd":"python3 - <<'PY'\nimport os\nos.system(\"rm -rf src\")\nPY","expect":"block","rule":"FR-6","why":"interpreter consumer reading stdin: the quoted rm inside os.system() is scanned","cwd":"repo"}
+{"id":"D103","cmd":"psql \"$DATABASE_URL\" <<SQL\nDROP TABLE users;\nSQL","expect":"block","rule":"FR-6","why":"SQL runner consumer with an unquoted delimiter (D14 is the quoted form)","cwd":"repo"}
+{"id":"D104","cmd":"bash -c \"$(cat <<EOF\nrm -rf src\nEOF\n)\"","expect":"block","rule":"FR-6","why":"cat inside a command substitution handed to bash -c: the header cannot be tokenised (open quote, $( ) so the whole command is scanned","cwd":"repo"}
+{"id":"D105","cmd":"eval \"$(cat <<EOF\nrm -rf src\nEOF\n)\"","expect":"block","rule":"FR-6","why":"cat inside a substitution handed to eval","cwd":"repo"}
+{"id":"D106","cmd":"source <(cat <<EOF\nrm -rf src\nEOF\n)","expect":"block","rule":"FR-6","why":"cat inside a process substitution handed to source","cwd":"repo"}
+{"id":"D107","cmd":"ssh deploy@host bash <<EOF\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"ssh runs its argument: interpreter class","cwd":"repo"}
+{"id":"D108","cmd":"docker exec -i app sh <<EOF\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"docker exec runs its argument: interpreter class","cwd":"repo"}
+{"id":"D109","cmd":"sudo bash <<EOF\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"sudo wrapper around a shell","cwd":"repo"}
+{"id":"D110","cmd":"cat <<EOF | xargs -I{} sh -c '{}'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a pipe target that runs its input (xargs sh -c) makes the pipeline interpreter class","cwd":"repo"}
+{"id":"D111","cmd":"env python3 - <<PY\nimport os\nos.system(\"rm -rf src\")\nPY","expect":"block","rule":"FR-6","why":"env wrapper around an interpreter","cwd":"repo"}
+{"id":"D112","cmd":"cat <<'EOF' | find . -name '*.bak' -exec rm -rf {} +\nsrc\nEOF","expect":"block","rule":"FR-6","why":"find -exec as the pipe target: interpreter class, the header's own find -exec rm is scanned","cwd":"repo"}
+{"id":"D113","cmd":"gh api -X DELETE repos/o/r/git/refs/heads/main --input - <<'EOF'\n{\"note\":\"rm -rf src\"}\nEOF","expect":"block","rule":"FR-6","why":"gh api --input - is not an allowlisted gh form, so the body is scanned in full (the ref deletion itself has no fence rule: R06)","cwd":"repo"}
+{"id":"D114","cmd":"yq -i '.' ci.yaml <<'EOF'\nrun: rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"yq in-place: the allowlist excludes -i, the body is scanned","cwd":"repo"}
+{"id":"D115","cmd":"jq -i '.cmd' <<'EOF'\n{\"cmd\": \"rm -rf src\"}\nEOF","expect":"block","rule":"FR-6","why":"jq with an in-place-shaped flag: the body is scanned","cwd":"repo"}
+{"id":"D116","cmd":"awk '{ system(\"rm -rf src\") }' <<'EOF'\nx\nEOF","expect":"block","rule":"FR-6","why":"awk can call system(): interpreter class, the header's own system() argument is scanned","cwd":"repo"}
+{"id":"D117","cmd":"sed 'e rm -rf src' <<'EOF'\nx\nEOF","expect":"block","rule":"FR-6","why":"sed with an e command is not the print-only form: interpreter class","cwd":"repo"}
+{"id":"D118","cmd":"make -f - <<'EOF'\nclean:\n\trm -rf src\nEOF","expect":"block","rule":"FR-6","why":"make reading a makefile from stdin runs its recipes: interpreter class","cwd":"repo"}
+{"id":"D119","cmd":"cat > x.sh <<'EOF'\nrm -rf src\nEOF\nbash x.sh","expect":"block","rule":"FR-6","why":"a heredoc written to x.sh and run on the same command (script extension and same-line execution)","cwd":"repo"}
+{"id":"D120","cmd":"cat > run <<'EOF'\nrm -rf src\nEOF\nchmod +x run && ./run","expect":"block","rule":"FR-6","why":"same-line execution of an extensionless target: chmod +x names the target outside a safe reader","cwd":"repo"}
+{"id":"D121","cmd":"tee setup.sh <<'EOF'\nrm -rf src\nEOF\nsource setup.sh","expect":"block","rule":"FR-6","why":"tee into a .sh then source on the same command","cwd":"repo"}
+{"id":"D122","cmd":"cat > cleanup.sh <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a .sh target with no later execution is executable content: scanned in full (the #1245 scrub let this through)","cwd":"repo"}
+{"id":"D123","cmd":"cat > cleanup <<'EOF'\n#!/bin/sh\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a shebang first line makes a plain-file target executable content (the #1245 scrub let this through)","cwd":"repo"}
+{"id":"D124","cmd":"tee .claude/hooks/safety/x.sh <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a write under .claude/hooks/ is executable content (and FR-SZ2-TEE blocks the System Zone write regardless)","cwd":"repo"}
+{"id":"D125","cmd":"cat >> ~/.bashrc <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"an rc file target is executable content","cwd":"repo"}
+{"id":"D126","cmd":"mycmd <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a consumer on neither list: full scan (the default)","cwd":"repo"}
+{"id":"D127","cmd":"cat > notes.md <<'EOF'\ncat <<'INNER'\nrm -rf src\nINNER\nEOF","expect":"block","rule":"FR-6","why":"a nested heredoc in the body forces the full scan","cwd":"repo"}
+{"id":"D128","cmd":"cat > notes.md <<$D\nrm -rf src\n$D","expect":"block","rule":"FR-6","why":"a variable-expanded delimiter cannot be paired: full scan","cwd":"repo"}
+{"id":"D129","cmd":"cat <<EOF > notes.md\necho ok && rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"per-segment scan: the segment after && starts with a fence verb","cwd":"repo"}
+{"id":"D130","cmd":"cat <<EOF > notes.md\n; rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"per-segment scan: the segment after ; starts with a fence verb","cwd":"repo"}
+{"id":"D131","cmd":"cat <<EOF > notes.md\n\\rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a leading backslash is stripped before the command word is matched","cwd":"repo"}
+{"id":"D132","cmd":"cat <<EOF > notes.md\n/bin/rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"an absolute path is reduced to its basename before matching","cwd":"repo"}
+{"id":"D133","cmd":"cat <<EOF > notes.md\ncommand rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"the command wrapper prefix is stripped","cwd":"repo"}
+{"id":"D134","cmd":"cat <<EOF > notes.md\nexec rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"the exec wrapper prefix is stripped","cwd":"repo"}
+{"id":"D135","cmd":"cat <<EOF > notes.md\nsudo rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"the sudo wrapper prefix is stripped","cwd":"repo"}
+{"id":"D136","cmd":"cat <<EOF > notes.md\nx=rm; $x -rf src\nEOF","expect":"block","rule":"FR-6","why":"a variable command word forces the full scan and is also scanned as rm, git and kubectl with the same arguments","cwd":"repo"}
+{"id":"D137","cmd":"cat <<EOF > notes.md\n$(rm -rf src)\nEOF","expect":"block","rule":"FR-6","why":"a command substitution under an unquoted delimiter runs when the heredoc is expanded: full scan","cwd":"repo"}
+{"id":"D138","cmd":"cat <<EOF > notes.md\n`rm -rf src`\nEOF","expect":"block","rule":"FR-6","why":"a backtick substitution under an unquoted delimiter: full scan","cwd":"repo"}
+{"id":"D139","cmd":"cat <<EOF > notes.md\neval \"rm -rf src\"\nEOF","expect":"block","rule":"FR-6","why":"an interpreter word inside the body forces the full scan","cwd":"repo"}
+{"id":"D140","cmd":"cat <<EOF > notes.md\ngit push --force origin main was refused\nEOF","expect":"block","rule":"FR-6","why":"fail closed: a prose line that begins with a fence verb is kept and scanned as a command (the documented limit of per-segment classification)","cwd":"repo"}
+{"id":"D141","cmd":"cat > notes.md <<'EOF'\n\u0001\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a control character anywhere in the command forces the full scan","cwd":"repo"}
+{"id":"D142","cmd":"cat <<'EOF' > \"$OUT\"\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a non-literal write target cannot be judged: interpreter class","cwd":"repo"}
+{"id":"B89","cmd":"gh api -X DELETE repos/o/r/git/refs/heads/main --input - <<'EOF'\n{\"ref\":\"refs/heads/main\"}\nEOF","expect":"allow","rule":"FR-6","why":"documented miss (cycle-129 Sprint 2): gh api -X DELETE has no fence rule of its own; the classifier scans the body in full (D113) and a benign body passes","cwd":"repo"}
diff --git a/tests/fixtures/fence-corpus/run-corpus.sh b/tests/fixtures/fence-corpus/run-corpus.sh
index c2d9fe50..c98c4290 100755
--- a/tests/fixtures/fence-corpus/run-corpus.sh
+++ b/tests/fixtures/fence-corpus/run-corpus.sh
@@ -2,26 +2,35 @@
 # run-corpus.sh — replay tests/fixtures/fence-corpus/corpus.jsonl through the
 # block-destructive-bash hook and summarise (cycle-125 Sprint 1, PRD FR-1).
 #
-# Usage: run-corpus.sh [--hook PATH] [--corpus PATH] [--json]
+# Usage: run-corpus.sh [--hook PATH] [--corpus PATH] [--json] [--knob-off] [--rows]
 # Each row: {id, cmd, expect: allow|block|residual, rule, why, cwd: repo|tmp, env?: {TMPDIR}}
 #   allow    → benign: the hook must exit 0
 #   block    → dangerous: the hook must exit 2
 #   residual → accepted false positive: counted, never gated
-# Output (text): one line per mismatch, then "benign P/T dangerous B/T residual R/T runtime_ms N";
+# --knob-off  writes destructive_command_guard.heredoc_classifier: false into the
+#             replay root's .loa.config.yaml (cycle-129 FR-6: the pre-cycle scan);
+#             compare it with the pre-change hook through --rows.
+# --rows      prints "<id> <exit code>" per row instead of the summary (for diffs).
+# Output (text): one line per mismatch, then
+#   "benign P/T dangerous B/T residual R/T runtime_ms N p95_ms M";
 # --json prints {benign_pass, benign_total, dangerous_block, dangerous_total,
-#   residual_pass, residual_total, runtime_ms, mismatches: [..]}.
+#   residual_pass, residual_total, runtime_ms, p95_ms, rows, mismatches: [..]}.
+# p95_ms is the 95th percentile of the per-row hook wall time (the hook process
+# only; the jq row parsing is outside the timed span).
 set -uo pipefail
 export LC_ALL=C
 root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
 hook="$root/.claude/hooks/safety/block-destructive-bash.sh"
 corpus="$root/tests/fixtures/fence-corpus/corpus.jsonl"
-json=0
+json=0 knob_off=0 rows_out=0
 while [[ $# -gt 0 ]]; do
   case "$1" in
     --hook) hook="$2"; shift 2 ;;
     --corpus) corpus="$2"; shift 2 ;;
     --json) json=1; shift ;;
-    *) echo "usage: run-corpus.sh [--hook PATH] [--corpus PATH] [--json]" >&2; exit 2 ;;
+    --knob-off) knob_off=1; shift ;;
+    --rows) rows_out=1; shift ;;
+    *) echo "usage: run-corpus.sh [--hook PATH] [--corpus PATH] [--json] [--knob-off] [--rows]" >&2; exit 2 ;;
   esac
 done
 [[ -x "$hook" || -f "$hook" ]] || { echo "hook not found: $hook" >&2; exit 2; }
@@ -33,19 +42,23 @@ repo="$work/repo"; scratch="$work/scratch"
 mkdir -p "$repo" "$scratch"
 export LOA_REPO_ROOT="$work"
 export LOA_AUDIT_REPLAY=1   # audit rows this replay writes carry replay: true (cycle-129 DEC-0167)
+if (( knob_off )); then
+  printf 'destructive_command_guard:\n  heredoc_classifier: false\n' > "$work/.loa.config.yaml"
+fi

 bp=0 bt=0 db=0 dt=0 rp=0 rt=0
 mismatches=()
-# Millisecond clock: $EPOCHREALTIME (bash ≥ 5) everywhere; GNU date fallback.
-now_ms() {
+durations=()
+# Microsecond clock: $EPOCHREALTIME (bash ≥ 5) everywhere; GNU date fallback.
+now_us() {
   if [[ -n "${EPOCHREALTIME:-}" ]]; then
     local s="${EPOCHREALTIME%.*}" us="${EPOCHREALTIME#*.}"
-    echo $(( s * 1000 + 10#${us:0:3} ))
+    echo $(( s * 1000000 + 10#${us:0:6} ))
   else
-    echo $(( $(date +%s%N) / 1000000 ))
+    echo $(( $(date +%s%N) / 1000 ))
   fi
 }
-start_ms=$(now_ms)
+start_us=$(now_us)
 while IFS= read -r row; do
   [[ -n "$row" ]] || continue
   id=$(jq -r '.id' <<<"$row"); cmd=$(jq -r '.cmd' <<<"$row"); expect=$(jq -r '.expect' <<<"$row")
@@ -53,11 +66,15 @@ while IFS= read -r row; do
   dir="$repo"; [[ "$cwd" == "tmp" ]] && dir="$scratch"
   payload=$(jq -cn --arg c "$cmd" '{tool_input: {command: $c}}')
   rc=0
+  t0=$(now_us)
   if [[ -n "$tmpdir" ]]; then
     (cd "$dir" && TMPDIR="$tmpdir" bash "$hook" <<<"$payload" >/dev/null 2>&1) || rc=$?
   else
     (cd "$dir" && env -u TMPDIR bash "$hook" <<<"$payload" >/dev/null 2>&1) || rc=$?
   fi
+  t1=$(now_us)
+  durations+=("$(( (t1 - t0) / 1000 ))")
+  (( rows_out )) && printf '%s %s\n' "$id" "$rc"
   case "$expect" in
     allow)    bt=$((bt+1)); if [[ $rc -eq 0 ]]; then bp=$((bp+1)); else mismatches+=("$id:expected-allow:rc=$rc"); fi ;;
     block)    dt=$((dt+1)); if [[ $rc -eq 2 ]]; then db=$((db+1)); else mismatches+=("$id:expected-block:rc=$rc"); fi ;;
@@ -65,15 +82,22 @@ while IFS= read -r row; do
     *) mismatches+=("$id:unknown-expect:$expect") ;;
   esac
 done < "$corpus"
-end_ms=$(now_ms)
-runtime=$(( end_ms - start_ms ))
+end_us=$(now_us)
+runtime=$(( (end_us - start_us) / 1000 ))
+n=${#durations[@]}
+p95=0
+if (( n > 0 )); then
+  idx=$(( (n * 95 + 99) / 100 ))      # nearest-rank: ceil(0.95 n)
+  p95=$(printf '%s\n' "${durations[@]}" | sort -n | sed -n "${idx}p")
+fi

+(( rows_out )) && exit 0
 if (( json )); then
   printf '%s\n' "${mismatches[@]+"${mismatches[@]}"}" | jq -R . | jq -s \
     --argjson bp "$bp" --argjson bt "$bt" --argjson db "$db" --argjson dt "$dt" \
-    --argjson rp "$rp" --argjson rt "$rt" --argjson ms "$runtime" \
-    '{benign_pass:$bp, benign_total:$bt, dangerous_block:$db, dangerous_total:$dt, residual_pass:$rp, residual_total:$rt, runtime_ms:$ms, mismatches: map(select(length>0))}'
+    --argjson rp "$rp" --argjson rt "$rt" --argjson ms "$runtime" --argjson p95 "$p95" --argjson n "$n" \
+    '{benign_pass:$bp, benign_total:$bt, dangerous_block:$db, dangerous_total:$dt, residual_pass:$rp, residual_total:$rt, runtime_ms:$ms, p95_ms:$p95, rows:$n, mismatches: map(select(length>0))}'
 else
   printf '%s\n' "${mismatches[@]+"${mismatches[@]}"}" | sed '/^$/d'
-  echo "benign $bp/$bt dangerous $db/$dt residual $rp/$rt runtime_ms $runtime"
+  echo "benign $bp/$bt dangerous $db/$dt residual $rp/$rt runtime_ms $runtime p95_ms $p95"
 fi
diff --git a/tests/fixtures/profiles/standard-oracle.json b/tests/fixtures/profiles/standard-oracle.json
